using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class HospitalProbe{static HospitalProbe(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("HospitalProbe.request"))return;File.Delete("HospitalProbe.request");try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var fs=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.name.StartsWith("Building_06_01_Material #26_0")).ToArray();File.WriteAllLines("FinalEnvironmentRoadReview/HospitalProbe.txt",new[]{"Selected="+(Selection.activeGameObject?Selection.activeGameObject.name:"none")}.Concat(fs.Select(f=>f.name+" bounds="+f.GetComponent<Renderer>().bounds+" transform="+f.transform.localToWorldMatrix)));foreach(var f in fs){var b=f.GetComponent<Renderer>().bounds;var flags=BindingFlags.Static|BindingFlags.NonPublic;var d=typeof(FinalPNGCityDetails).GetMethod("Read",flags).Invoke(null,new object[]{f.sharedMesh});var p=(Vector3[])d.GetType().GetField("p").GetValue(d);var ids=(int[])d.GetType().GetField("ids").GetValue(d);File.WriteAllLines("FinalEnvironmentRoadReview/Hospital-"+f.GetInstanceID()+".csv",new[]{"i,x,y,z"}.Concat(Enumerable.Range(0,p.Length).Select(i=>{var w=f.transform.TransformPoint(p[i]);return i+","+w.x+","+w.y+","+w.z;})));File.WriteAllText("FinalEnvironmentRoadReview/Hospital-"+f.GetInstanceID()+"-ids.txt",string.Join(",",ids));typeof(FinalPNGCityDetails).GetMethod("Capture",flags).Invoke(null,new object[]{scene,b.center+new Vector3(0,10,145),b.center,"Hospital-Before-"+f.GetInstanceID()});}}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/HospitalProbe.txt",e.ToString());}}}
